import numpy as np
from scipy.stats import norm

def bs_call(S, K, T, r, sigma, q=0.0):
    d1 = (np.log(S / K) + (r - q + 0.5 * sigma**2) * T) / (sigma * np.sqrt(T))
    d2 = d1 - sigma * np.sqrt(T)
    return S * np.exp(-q*T) * norm.cdf(d1) - K * np.exp(-r*T) * norm.cdf(d2)

def implied_vol_call_bisection(market_price, S, K, T, r, q=0.0,
                               low=1e-6, high=5.0, tol=1e-8, max_iter=200):
    """Compute call implied volatility using bisection."""
    if market_price <= 0:
        raise ValueError("market_price must be positive")

    f_low = bs_call(S, K, T, r, low, q) - market_price
    f_high = bs_call(S, K, T, r, high, q) - market_price

    if f_low * f_high > 0:
        raise ValueError("Root is not bracketed. Check inputs or bounds.")

    for _ in range(max_iter):
        mid = 0.5 * (low + high)
        f_mid = bs_call(S, K, T, r, mid, q) - market_price

        if abs(f_mid) < tol:
            return mid

        if f_low * f_mid <= 0:
            high = mid
            f_high = f_mid
        else:
            low = mid
            f_low = f_mid

    return 0.5 * (low + high)

