def max_profit_one_trade(prices):
    if len(prices) < 2:
        return 0.0

    min_price = prices[0]
    best_profit = 0.0

    for price in prices[1:]:
        best_profit = max(best_profit, price - min_price)
        min_price = min(min_price, price)

    return best_profit

