def bisection(f, a, b, tol=1e-10, max_iter=100):
    fa = f(a)
    fb = f(b)

    if fa * fb > 0:
        raise ValueError("Root is not bracketed.")

    for _ in range(max_iter):
        mid = 0.5 * (a + b)
        fm = f(mid)

        if abs(fm) < tol or 0.5 * (b - a) < tol:
            return mid

        if fa * fm <= 0:
            b = mid
            fb = fm
        else:
            a = mid
            fa = fm

    return 0.5 * (a + b)

