    std::map<double, double, std::greater<double>> bids; // highest first
    std::map<double, double> asks;                       // lowest first

    void update_bid(double price, double size) {
        if (size == 0.0) bids.erase(price);
        else bids[price] = size;
    }

    void update_ask(double price, double size) {
        if (size == 0.0) asks.erase(price);
        else asks[price] = size;
    }

    double best_bid() const { return bids.begin()->first; }
    double best_ask() const { return asks.begin()->first; }
};

def intersect_sorted(a, b):
    i = j = 0
    out = []

    while i < len(a) and j < len(b):
        if a[i] == b[j]:
            out.append(a[i])
            i += 1
            j += 1
        elif a[i] < b[j]:
            i += 1
        else:
            j += 1

    return out

