print(implementation_shortfall(trades, decision_price=100.0, side="buy"))

def check_sequence_numbers(messages):
    gaps = []
    duplicates = []

    seen = set()
    previous = None

    for msg in messages:
        seq = msg["seq"]

        if seq in seen:
            duplicates.append(seq)

        if previous is not None and seq != previous + 1:
            gaps.append((previous + 1, seq - 1))

        seen.add(seq)
        previous = seq

    return {"gaps": gaps, "duplicates": duplicates}

messages = [{"seq": 1}, {"seq": 2}, {"seq": 4}, {"seq": 4}]
print(check_sequence_numbers(messages))

